function renderProductTabs() {
    const tabsWrap = document.getElementById("product-tabs-bar");
    if (!tabsWrap) return;
    tabsWrap.innerHTML = "";

    const categories = ["PTS AI 铜箔", "HIS 载体铜箔", "DBJ 双晶铜箔"];

    // 确定当前选中的大类
    let currentActiveCategory = "HIS 载体铜箔";
    if (state.activeProduct) {
        const cat = state.activeProduct.category;
        if (cat === "背板双晶铜箔" || cat === "DBJ 双晶铜箔") {
            currentActiveCategory = "DBJ 双晶铜箔";
        } else if (cat === "PTS AI 铜箔") {
            currentActiveCategory = "PTS AI 铜箔";
        } else {
            currentActiveCategory = "HIS 载体铜箔";
        }
    }

    categories.forEach(catName => {
        const item = document.createElement("div");
        const isTabActive = catName === currentActiveCategory;
        item.className = `prod-tab-item ${isTabActive ? 'active' : ''}`;

        // 查找该大类下的所有产品，并根据其状态判定圆点颜色
        const dbCats = catName === "DBJ 双晶铜箔" ? ["DBJ 双晶铜箔", "背板双晶铜箔"] : [catName];
        const subProds = (state.products || []).filter(p => dbCats.includes(p.category));

        let dotClass = "gray";
        if (subProds.some(p => p.status === "量产中")) {
            dotClass = "green";
        } else if (subProds.some(p => p.status.includes("审批"))) {
            dotClass = "yellow";
        } else if (subProds.some(p => ["溅镀金属化中", "溅镀开发中", "生箔电镀中", "PA后处理中", "PB涂布中", "测试验证中"].includes(p.status))) {
            dotClass = "blue";
        }

        item.innerHTML = `
            <span class="prod-tab-status-dot ${dotClass}"></span>
            <strong style="font-size:0.8rem; font-weight:700;">${catName}</strong>
            <span style="opacity:0.75; font-size:0.7rem; font-weight:normal;">(${subProds.length}款型号)</span>
        `;

        item.addEventListener("click", () => {
            // 点击大类页签时，自动切换到该大类下的第一个产品
            if (subProds.length > 0) {
                state.activeProductId = subProds[0].id;
                saveStateToLocalStorage();
                renderProductTabs();
                loadProductDetails(subProds[0].id);
            } else {
                showToast(`当前类别 ${catName} 下暂无产品`, "warning");
            }
        });

        tabsWrap.appendChild(item);
    });
}

