function autoDeriveProjectNameAndCode() {
    const cat = document.getElementById("proj-category").value;
    if (!cat) return;

    // 1. 匹配缩写
    let catAbbr = "PTS-AI";
    if (cat === "PTS AI 铜箔") catAbbr = "PTS-AI";
    else if (cat === "HIS 载体铜箔") catAbbr = "HIS-Carrier";
    else if (cat === "DBJ 双晶铜箔" || cat === "背板双晶铜箔") catAbbr = "DBJ";

    // 统一 DBJ 类别（将旧名称常规化到新对应）
    const normalizedCat = (cat === "背板双晶铜箔") ? "DBJ 双晶铜箔" : cat;

    // 2. 动态分析当前 state.products 提取最大流水号（兼容旧名 背板双晶铜箔 和新名 DBJ 双晶铜箔）
    let maxNum = 0;
    if (state.products && state.products.length > 0) {
        state.products.forEach(p => {
            const pCat = (p.category === "背板双晶铜箔") ? "DBJ 双晶铜箔" : p.category;
            if (pCat === normalizedCat) {
                const parts = p.code.split("-");
                const lastPart = parts[parts.length - 1];
                const num = parseInt(lastPart, 10);
                if (!isNaN(num) && num > maxNum) {
                    maxNum = num;
                }
            }
        });
    }

    // 3. 自增下一个流水号并格式化为两位数
    const nextNum = maxNum + 1;
    const formattedNum = nextNum < 10 ? `0${nextNum}` : `${nextNum}`;
    const code = `${catAbbr}-${formattedNum}`;

    document.getElementById("proj-code").value = code;

    // 4. 品名支持自定义：只有在当前输入为空时才自动填充默认类别名建议，绝不覆盖用户已填入的自定义品名
    const nameInput = document.getElementById("proj-name");
    if (nameInput && !nameInput.value.trim()) {
        nameInput.value = cat;
    }
}

