    sups.forEach(s => {
        let statusBadge = s.status === '活跃' ? '<span class="badge badge-green">活跃</span>' : (s.status === '暂停' ? '<span class="badge badge-warning">暂停</span>' : '<span class="badge badge-danger">淘汰</span>');
