                { label:'物料分类',     val: mat.mat_category || '—' },
                { label:'申请人',       val: mat.apply_by || '—' },
                { label:'申请日期',     val: mat.apply_date || '—' },
                { label:'承认负责人',   val: mat.conclusion_by || '—' },
                { label:'正式承认日期', val: mat.conclusion_date || '—' },
