// 删除物料承认记录
window.deleteMqcMaterial = function(id) {
    const role = state.currentUserRole;
    if (!['Admin', '管理员', 'Product Manager', '产品经理'].includes(role)) {
        showToast("仅管理员或产品经理有权删除物料承认记录", "warning"); return;
    }
    if (!confirm("确定要删除该物料承认台账吗？关联供应商信息也将一并删除，且不可恢复！")) return;
    fetch("/api/mqc/materials/delete", {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ id: id })
    }).then(r => r.json()).then(res => {
        if (res.error) { showToast(res.error, "error"); }
        else { showToast("物料及关联供应商渠道已成功删除！", "success"); fetchMqcData(); }
    }).catch(() => showToast("删除失败", "error"));
};

// 打开供应商渠道维护弹窗
window.openMqcSupplierModal = function(matCode) {
    const mat = state.mqcMaterials.find(m => m.mat_code === matCode);
    if (!mat) return;
    document.getElementById("mqc-supplier-mat-label").innerText = `${mat.mat_name} (${mat.mat_code})`;
    document.getElementById("mqc-sup-mat-code").value = matCode;
    resetMqcSupForm();
    renderMqcSupplierList(matCode);
    openModal("modal-mqc-supplier");
};

// 重置供应商填写表单
window.resetMqcSupForm = function() {
    ['mqc-sup-id','mqc-sup-name','mqc-sup-contact','mqc-sup-phone','mqc-sup-risk-note'].forEach(id => {
        const el = document.getElementById(id);
        if (el) { el.value = ''; el.style.borderColor = ''; }
    });
    const tier = document.getElementById('mqc-sup-tier'); if (tier) tier.value = '一供';
    const risk = document.getElementById('mqc-sup-risk'); if (risk) risk.value = '中';
    const stat = document.getElementById('mqc-sup-status'); if (stat) stat.value = '活跃';
    const date = document.getElementById('mqc-sup-approved-date');
    if (date) date.value = new Date().toISOString().split('T')[0];
};

